CREATE TABLE app_users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, profile jsonb NOT NULL, settings jsonb NOT NULL, policy_version bigint NOT NULL DEFAULT 1, intake_alias text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (tenant_id uuid REFERENCES organizations(id), user_id uuid REFERENCES app_users(id), role text NOT NULL CHECK(role IN ('PLATFORM_ADMIN','ORG_ADMIN','FINANCE_MANAGER','PROCESSOR','REVIEWER','APPROVER','AUDITOR')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE invitations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, role text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_units (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, gstin text, state text NOT NULL, address text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE suppliers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, gstin text, pan text, state text, address text, contact text, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE INDEX supplier_search ON suppliers(tenant_id,lower(name));
CREATE UNIQUE INDEX supplier_gstin ON suppliers(tenant_id,gstin) WHERE gstin IS NOT NULL AND gstin <> '';
CREATE TABLE purchase_orders (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), supplier_id uuid NOT NULL, number text NOT NULL, date date NOT NULL, currency text NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')), version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,supplier_id) REFERENCES suppliers(tenant_id,id));
CREATE TABLE po_lines (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, po_id uuid NOT NULL, code text NOT NULL, description text NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), price numeric(20,6) NOT NULL CHECK(price>=0), tax_rate numeric(9,6) NOT NULL CHECK(tax_rate>=0 AND tax_rate<=100), UNIQUE(tenant_id,id), UNIQUE(tenant_id,po_id,code), FOREIGN KEY(tenant_id,po_id) REFERENCES purchase_orders(tenant_id,id));
CREATE TABLE ingestion_batches (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), actor uuid NOT NULL REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE invoices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), batch_id uuid, creator uuid NOT NULL REFERENCES app_users(id), version bigint NOT NULL DEFAULT 0, processing_state text NOT NULL DEFAULT 'QUEUED', business_state text NOT NULL DEFAULT 'NEEDS_REVIEW', data jsonb NOT NULL DEFAULT '{}', supplier_id uuid, invoice_number text, normalized_number text, financial_year text, document_type text, invoice_date date, total numeric(20,4), currency text, sha256 text NOT NULL, storage_key text NOT NULL UNIQUE, filename text NOT NULL, mime text NOT NULL, source text NOT NULL, source_metadata jsonb NOT NULL DEFAULT '{}', request_key text NOT NULL, approved_version bigint, approver uuid, preparer uuid, assignee uuid, error text, match_status text NOT NULL DEFAULT 'NOT_EVALUATED', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(tenant_id,id), UNIQUE(tenant_id,request_key), FOREIGN KEY(tenant_id,batch_id) REFERENCES ingestion_batches(tenant_id,id), FOREIGN KEY(tenant_id,supplier_id) REFERENCES suppliers(tenant_id,id), FOREIGN KEY(tenant_id,assignee) REFERENCES memberships(tenant_id,user_id), FOREIGN KEY(tenant_id,approver) REFERENCES memberships(tenant_id,user_id));
CREATE INDEX invoice_queue ON invoices(tenant_id,business_state,created_at DESC);
CREATE INDEX invoice_processing ON invoices(tenant_id,processing_state,created_at DESC);
CREATE INDEX invoice_supplier ON invoices(tenant_id,supplier_id,invoice_date);
CREATE INDEX invoice_identity ON invoices(tenant_id,normalized_number,financial_year);
CREATE INDEX invoice_hash ON invoices(tenant_id,sha256);
CREATE TABLE invoice_versions (tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, data jsonb NOT NULL, provenance text NOT NULL, actor uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,invoice_id,version), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE processing_jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, state text NOT NULL DEFAULT 'QUEUED', attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE UNIQUE INDEX active_processing_job ON processing_jobs(tenant_id,invoice_id) WHERE state IN ('QUEUED','RUNNING');
CREATE INDEX ready_jobs ON processing_jobs(state,available_at);
CREATE TABLE extraction_runs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, provider text NOT NULL, model text NOT NULL, status text NOT NULL, raw jsonb, normalized jsonb, evidence jsonb, error text, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE evaluation_runs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, policy_version bigint NOT NULL, policy jsonb NOT NULL, findings jsonb NOT NULL, matches jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,invoice_id,version) REFERENCES invoice_versions(tenant_id,invoice_id,version));
CREATE TABLE exceptions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, rule_id text NOT NULL, field text NOT NULL, severity text NOT NULL, explanation text NOT NULL, evidence jsonb NOT NULL, status text NOT NULL DEFAULT 'OPEN', assignee uuid, reason text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id), FOREIGN KEY(tenant_id,assignee) REFERENCES memberships(tenant_id,user_id));
CREATE INDEX exception_queue ON exceptions(tenant_id,status,created_at);
CREATE TABLE duplicate_decisions (tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, candidate_id uuid NOT NULL, version bigint NOT NULL, reason text NOT NULL, actor uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,invoice_id,candidate_id,version), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id), FOREIGN KEY(tenant_id,candidate_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE approval_decisions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, actor uuid NOT NULL, decision text NOT NULL, reason text NOT NULL, policy_version bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,invoice_id,version) REFERENCES invoice_versions(tenant_id,invoice_id,version));
CREATE TABLE approved_identities (tenant_id uuid NOT NULL, identity_key text NOT NULL, invoice_id uuid NOT NULL, PRIMARY KEY(tenant_id,identity_key), FOREIGN KEY(tenant_id,invoice_id) REFERENCES invoices(tenant_id,id));
CREATE TABLE po_allocations (tenant_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, po_line_id uuid NOT NULL, quantity numeric(20,6) NOT NULL CHECK(quantity>0), amount numeric(20,4) NOT NULL CHECK(amount>=0), PRIMARY KEY(tenant_id,invoice_id,version,po_line_id), FOREIGN KEY(tenant_id,invoice_id,version) REFERENCES invoice_versions(tenant_id,invoice_id,version), FOREIGN KEY(tenant_id,po_line_id) REFERENCES po_lines(tenant_id,id));
CREATE TABLE export_batches (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), actor uuid NOT NULL REFERENCES app_users(id), request_key text NOT NULL, status text NOT NULL DEFAULT 'PREPARING', profile jsonb NOT NULL, reason text, content bytea, error text, sha256 text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(tenant_id,id), UNIQUE(tenant_id,request_key));
CREATE TABLE export_records (tenant_id uuid NOT NULL, batch_id uuid NOT NULL, invoice_id uuid NOT NULL, version bigint NOT NULL, PRIMARY KEY(tenant_id,batch_id,invoice_id), FOREIGN KEY(tenant_id,batch_id) REFERENCES export_batches(tenant_id,id), FOREIGN KEY(tenant_id,invoice_id,version) REFERENCES invoice_versions(tenant_id,invoice_id,version));
CREATE UNIQUE INDEX initial_export_once ON export_records(tenant_id,invoice_id,version,batch_id);
CREATE TABLE notifications (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, resource_id uuid, title text NOT NULL, event_key text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,user_id,event_key), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), actor text NOT NULL, action text NOT NULL, resource_id uuid, summary jsonb NOT NULL, reason text, correlation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_timeline ON audit_events(tenant_id,resource_id,created_at DESC);
CREATE FUNCTION prevent_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable history cannot be modified'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_mutation();
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON invoice_versions FOR EACH ROW EXECUTE FUNCTION prevent_mutation();
CREATE TRIGGER immutable_approvals BEFORE UPDATE OR DELETE ON approval_decisions FOR EACH ROW EXECUTE FUNCTION prevent_mutation();
CREATE TABLE email_events (provider_id text PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations(id), metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL PRIMARY KEY, SESSION_ID CHAR(36) NOT NULL, CREATION_TIME BIGINT NOT NULL, LAST_ACCESS_TIME BIGINT NOT NULL, MAX_INACTIVE_INTERVAL INT NOT NULL, EXPIRY_TIME BIGINT NOT NULL, PRINCIPAL_NAME VARCHAR(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES (SESSION_PRIMARY_ID CHAR(36) NOT NULL REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE, ATTRIBUTE_NAME VARCHAR(200) NOT NULL, ATTRIBUTE_BYTES BYTEA NOT NULL, PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME));
